using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using BepInEx;using BepInEx.Unity.Mono;using UnityEngine;using InFalsusStudio;using InFalsusStudio.Core;using InFalsusStudio.Gameplay;using InFalsusStudio.NativeVisual;using InFalsusStudio.NativeEditorUI;using InFalsusStudio.VideoRender;
[BepInPlugin("test.native.hud.refine","HUD native refine checks","1.0.0")]
public class NativeRefineChecks:BaseUnityPlugin {
 const BindingFlags F=BindingFlags.Static|BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 string root=@"E:\RhythmGame\InFalsusStudio+\feature_work\hud-native-refine";int count,failures;
 void Check(bool ok,string name){count++;File.AppendAllText(root+"/checks.txt",(ok?"PASS ":"FAIL ")+name+"\n");if(!ok)failures++;}
 bool Near(float a,float b){return Math.Abs(a-b)<.0001f;}
 void Logic(){
  var a=new NativeGaugeTransition();a.Advance(4,0);Check(a.Current==4&&a.Alpha[5]==1&&a.Alpha[4]==0,"AP to FC starts with old image visible");a.Advance(4,.15);Check(Near(a.Alpha[5],.5f)&&Near(a.Alpha[4],.5f),"native 0.3s SineInOut midpoint crossfade");a.Advance(4,.3);Check(Near(a.Alpha[4],1)&&Near(a.Alpha[5],0),"final state completes in 0.3s");
  a=new NativeGaugeTransition();a.Advance(2,0);Check(a.Current==4&&a.Alpha[4]==1,"multi-state downgrade first commits FC");a.Advance(2,.01);Check(a.Current==3&&a.Alpha[3]==1,"multi-state downgrade commits positive-extra next frame");a.Advance(2,.02);a.Advance(2,.17);Check(Near(a.Alpha[2],.5f)&&Near(a.Alpha[3],.5f),"only final downgrade step uses 0.3s fade");a.Advance(2,.32);Check(Near(a.Alpha[2],1)&&Near(a.PositiveNumber,1),"positive number fades in within 0.2s");a.Advance(1,.33);a.Advance(1,.43);Check(Near(a.PositiveNumber,.45f)&&Near(a.NegativeNumber,.55f),"positive and negative number opacity switches gradually");
  a=new NativeGaugeTransition();a.Advance(4,0);a.Advance(1,.1);Check(a.Current==4,"new target during fade waits for active native step");a.Advance(1,.3);Check(a.Current==3&&a.Target==1,"latest target continues after active fade");a.Advance(5,.31);Check(a.Current==5&&a.Alpha[5]==1,"upgrade to AP follows native immediate branch");
  a=new NativeGaugeTransition();a.Advance(4,0);a.Advance(4,.3);var b=new NativeGaugeTransition();b.Advance(4,0);for(int i=1;i<=6;i++)b.Advance(4,i*.05);Check(Near(a.Alpha[4],b.Alpha[4]),"fade is independent of frame count");b.Advance(5,-1);Check(b.Current==5&&b.Alpha[5]==1,"backward export clock resets stale animation");
 }
 void Save(RenderTexture surface,string name){var old=RenderTexture.active;RenderTexture.active=surface;var t=new Texture2D(surface.width,surface.height,TextureFormat.RGBAFloat,false,true);t.ReadPixels(new Rect(0,0,t.width,t.height),0,0);t.Apply();var px=t.GetPixels();Check(px.Any(c=>c.a>.1)&&px.All(c=>!float.IsNaN(c.r)&&!float.IsInfinity(c.r)),name+" has valid visible GPU output");File.WriteAllBytes(root+"/"+name+".png",ImageConversion.EncodeToPNG(t));Destroy(t);RenderTexture.active=old;}
 void Frame(StudioBootstrap boot,RenderTexture surface,double time,string name){RenderClock.Elapsed=time;RenderTexture.active=surface;GL.Clear(false,true,new Color(.03f,.06f,.08f,1));CaptureCanvas.Begin(surface);NativePresentation.DrawHud(boot);NativePresentation.DrawLifeGauge(boot);CaptureCanvas.End();Save(surface,name);}
 IEnumerator Start(){if(!Environment.GetCommandLineArgs().Contains("-native-refine-checks"))yield break;root=Environment.GetEnvironmentVariable("REFINE_OUT")??root;Directory.CreateDirectory(root);File.WriteAllText(root+"/checks.txt","Native HUD refine checks\n");yield return new WaitForSeconds(4);try{Logic();var ui=NativeEditorUIPlugin.I;var boot=UnityEngine.Object.FindObjectOfType<StudioBootstrap>();ui.Bind(boot);NativeEditorUIPlugin.Set(boot,"showReleaseNotes",false);NativeEditorUIPlugin.Set(boot,"guiShowReleaseNotes",false);var load=typeof(StudioBootstrap).GetMethod("LoadDocument",F);var ps=load.GetParameters();var args=new object[ps.Length];args[0]=SpcDocument.Parse("chart(120,4)\ntap(1000,1,1)\n");for(int j=1;j<args.Length;j++)args[j]=ps[j].DefaultValue;load.Invoke(boot,args);NativeEditorUIPlugin.Set(boot,"songJacket",null);NativeEditorUIPlugin.Set(boot,"guiSongTitle","Outliers");NativeEditorUIPlugin.Set(boot,"guiSongArtist","Xyris");NativeEditorUIPlugin.Set(boot,"guiSongIndex",3);NativeEditorUIPlugin.Set(boot,"guiSongRating","14");NativeEditorUIPlugin.Set(boot,"showSongHud",true);NativeEditorUIPlugin.Set(boot,"guiShowSongHud",true);ui.SetGameplayEnabled(true);NativeVisualPlugin.ApGauge.Value=true;Check(NativePresentation.Images.ContainsKey("nojacket")&&NativePresentation.Images["nojacket"].width==256,"original 256px NO JACKET asset loaded");
  var tr=NativeEditorUIPlugin.Val<StudioTransport>(boot,"transport");tr.Seek(1000);Check(GameplaySession.Enter(boot),"real gameplay session starts");GameplaySession.Phase=GameplayPhase.LeadIn;GameplaySession.LeadDeadline=Time.realtimeSinceStartupAsDouble+1000;RenderClock.Active=true;int w=int.Parse(Environment.GetEnvironmentVariable("REFINE_W")??"1920"),h=w*9/16;RenderClock.Width=w;RenderClock.Height=h;var surface=new RenderTexture(w,h,0,RenderTextureFormat.ARGBHalf,RenderTextureReadWrite.Linear);surface.Create();boot.ViewCamera.targetTexture=surface;boot.ViewCamera.rect=new Rect(0,0,1,1);NativeEditorUIPlugin.Set(boot,"hudScale",w/1920f);NativePresentation.gaugeAnimation=new NativeGaugeTransition();NativePresentation.gaugeOwner=GameplaySession.Engine;Frame(boot,surface,0,"ap-nojacket");GameplaySession.Engine.Near=1;Frame(boot,surface,0,"fc-start");Frame(boot,surface,.15,"fc-mid");Check(Near(NativePresentation.gaugeAnimation.Alpha[4],.5f),"real gauge draws intermediate opacity");Frame(boot,surface,.3,"fc-end");GameplaySession.Engine.Break=1;GameplaySession.Engine.Gauge=8;Frame(boot,surface,.3,"positive-start");Frame(boot,surface,.45,"positive-mid");Frame(boot,surface,.6,"positive-end");Check(NativeEditorUIPlugin.Get(boot,"songJacket")==null,"fallback does not modify chart jacket metadata");RenderClock.Active=false;CaptureCanvas.Release();GameplaySession.Exit();Check(!GameplaySession.Active,"gameplay exits cleanly after gauge rendering");boot.ViewCamera.targetTexture=null;RenderTexture.active=null;Destroy(surface);
 }catch(Exception e){failures++;File.AppendAllText(root+"/checks.txt","FAIL exception "+e+"\n");}File.AppendAllText(root+"/checks.txt","DONE checks="+count+" failures="+failures+"\n");Application.Quit();}
}
